4.4 CDA - clinical documents in XML
A CDA (Clinical Document Architecture) document is XML with a fixed header and structured body. It represents whole documents — discharge summaries, referral notes. We parse a minimal fragment with xml2.

# CDA (Clinical Document Architecture) is XML: nested tags instead of pipes.
# It is used for whole documents (discharge summaries, referral notes) that a
# human can also open and read.
#
# The important nested pieces in this fragment:
#   &lt;id extension="P1001"/&gt;              → patient ID
#   &lt;given&gt;Ava&lt;/given&gt;&lt;family&gt;Khan&lt;/family&gt;  → name
#   &lt;administrativeGenderCode code="F"/&gt; → sex
#   &lt;birthTime value="19680312"/&gt;        → date of birth
#   &lt;code code="4548-4" .../&gt;            → LOINC for A1c
#   &lt;value unit="%" value="7.2"/&gt;        → the result
#
# xmlns="urn:hl7-org:v3" is the CDA namespace — we will need it when we search.
cda &lt;- '&lt;?xml version="1.0"?&gt;
&lt;ClinicalDocument xmlns="urn:hl7-org:v3"&gt;
  &lt;recordTarget&gt;
    &lt;patientRole&gt;
      &lt;id extension="P1001"/&gt;
      &lt;patient&gt;
        &lt;name&gt;&lt;given&gt;Ava&lt;/given&gt;&lt;family&gt;Khan&lt;/family&gt;&lt;/name&gt;
        &lt;administrativeGenderCode code="F"/&gt;
        &lt;birthTime value="19680312"/&gt;
      &lt;/patient&gt;
    &lt;/patientRole&gt;
  &lt;/recordTarget&gt;
  &lt;component&gt;
    &lt;observation&gt;
      &lt;code code="4548-4" codeSystemName="LOINC" displayName="Hemoglobin A1c"/&gt;
      &lt;value unit="%" value="7.2"/&gt;
    &lt;/observation&gt;
  &lt;/component&gt;
&lt;/ClinicalDocument&gt;'
cat(substr(cda, 1, 180), "...\n")  # print just the start so you see the shape without a wall of XML

&lt;?xml version="1.0"?&gt;
&lt;ClinicalDocument xmlns="urn:hl7-org:v3"&gt;
  &lt;recordTarget&gt;
    &lt;patientRole&gt;
      &lt;id extension="P1001"/&gt;
      &lt;patient&gt;
        &lt;name&gt;&lt;given&gt;Ava&lt;/given&gt;&lt;fa ...



# xml2 is a CRAN package (a wrapper around libxml2) — no extra install beyond
# what this series already uses. It turns the XML string into a tree of nodes
# we can search.
library(xml2)

# CDA tags live in a namespace. xml_find_first() needs that namespace or it
# will find nothing. We give it a short nickname "v3" so paths can say
# v3:patient, v3:name, etc.
ns &lt;- c(v3 = "urn:hl7-org:v3")

doc &lt;- read_xml(cda)  # parse the XML string into a tree; doc is &lt;ClinicalDocument&gt;

# .// means "search anywhere below the root". Paths walk the nested tags.
# xml_text()       = the words between a tag pair, e.g. &lt;given&gt;Ava&lt;/given&gt; → "Ava"
# xml_attr(x, "code") = an attribute on the tag, e.g. code="F" → "F"
given  &lt;- xml_text(xml_find_first(doc, ".//v3:patient/v3:name/v3:given", ns))
family &lt;- xml_text(xml_find_first(doc, ".//v3:patient/v3:name/v3:family", ns))
sex    &lt;- xml_attr(xml_find_first(doc, ".//v3:administrativeGenderCode", ns), "code")
dob    &lt;- xml_attr(xml_find_first(doc, ".//v3:birthTime", ns), "value")
obs    &lt;- xml_attr(xml_find_first(doc, ".//v3:observation/v3:code", ns), "displayName")
val    &lt;- xml_find_first(doc, ".//v3:observation/v3:value", ns)

cat(sprintf("Patient : %s %s  (sex=%s, dob=%s)\n", given, family, sex, dob))

Patient : Ava Khan  (sex=F, dob=19680312)

cat(sprintf("Observation: %s = %s %s\n", obs, xml_attr(val, "value"), xml_attr(val, "unit")))

Observation: Hemoglobin A1c = 7.2 %

5.5 Profiles and validation
A FHIR profile is a set of rules that further restricts or customizes the base FHIR specification for a particular context or country. For example, the US Core profile specifies that certain fields in a Patient resource are required for use in the United States.
Validation is the process of checking that a FHIR resource adheres to its schema and any applicable profile. In this notebook we check the base FHIR schema with a small hand-written validate_observation() function whenever we build a resource. If you provide invalid or incomplete data, it immediately stop()s with a clear error. This explicit validation step is a critical first step to ensure that the data you’re working with is correct and trustworthy (you’ll see more on advanced data quality in Module 8).

# We enforce the FHIR schema by hand, at construction time.
# Observation.status is a coded field: it must be one of
#   registered | preliminary | final | amended | corrected | cancelled | ...
# Passing a made-up value stop()s with a clear message instead of silently
# shipping a broken resource. That is your first data-quality gate.
validate_observation &lt;- function(res) {
  allowed_status &lt;- c("registered", "preliminary", "final", "amended",
                       "corrected", "cancelled", "entered-in-error", "unknown")
  if (!(res$status %in% allowed_status)) {
    stop(sprintf(
      "1 validation error for Observation\nstatus\n  Input should be a valid FHIR observation-status code, got '%s'",
      res$status
    ))
  }
  res
}

tryCatch({
  bad &lt;- validate_observation(list(
    resourceType = "Observation",
    status = "not-a-real-status",  # invalid — FHIR does not allow this string
    code = list(coding = list(list(code = "x")))
  ))
}, error = function(e) {
  cat("Schema validation rejected the resource:\n")
  cat(" ", strsplit(conditionMessage(e), "\n")[[1]][1], "\n")  # first line of the error is enough
  cat("  -&gt; 'status' must be a valid FHIR observation-status code\n")
})

